"use client"

import * as React from "react"
import { Menubar as MenubarPrimitive } from "@base-ui/react/menubar"
import { Menu as MenuPrimitive } from "@base-ui/react/menu"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

// Base UI className can be a state function; the wrappers feed it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const MenubarMenu = MenuPrimitive.Root
const MenubarGroup = MenuPrimitive.Group
const MenubarPortal = MenuPrimitive.Portal
const MenubarSub = MenuPrimitive.SubmenuRoot
const MenubarRadioGroup = MenuPrimitive.RadioGroup

const contentStyles =
  "origin-(--transform-origin) z-50 min-w-[12rem] overflow-hidden p-1 " +
  "rounded-lg border border-border " +
  "bg-popover text-popover-foreground " +
  "[box-shadow:var(--shadow-l)] " +
  "transition-[opacity,transform,scale] duration-fast " +
  "data-starting-style:opacity-0 data-starting-style:scale-95 data-ending-style:opacity-0"

const itemStyles =
  "relative flex cursor-default select-none items-center gap-2 rounded-md px-2 py-1.5 text-sm outline-none " +
  "transition-[background-color,color] duration-fast " +
  "focus:bg-accent focus:text-accent-foreground " +
  "data-[disabled]:pointer-events-none data-[disabled]:opacity-50"

function Menubar({ className, ...props }: WithClassName<MenubarPrimitive.Props>) {
  return (
    <MenubarPrimitive
      className={cn(
        "flex h-10 items-center gap-1 rounded-lg p-1",
        "bg-card text-card-foreground border border-border",
        "[box-shadow:var(--shadow-s)]",
        className
      )}
      {...props}
    />
  )
}
Menubar.displayName = "Menubar"

function MenubarTrigger({
  className,
  ...props
}: WithClassName<MenuPrimitive.Trigger.Props>) {
  return (
    <MenuPrimitive.Trigger
      className={cn(
        "flex cursor-default select-none items-center rounded-md px-3 py-1.5 text-sm font-medium outline-none",
        "transition-[background-color,color] duration-fast",
        "focus:bg-accent focus:text-accent-foreground",
        "data-popup-open:bg-accent data-popup-open:text-accent-foreground",
        className
      )}
      {...props}
    />
  )
}
MenubarTrigger.displayName = "MenubarTrigger"

function MenubarSubTrigger({
  className,
  inset,
  children,
  ...props
}: WithClassName<MenuPrimitive.SubmenuTrigger.Props> & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.SubmenuTrigger
      className={cn(
        itemStyles,
        "data-popup-open:bg-accent data-popup-open:text-accent-foreground",
        inset && "pl-8",
        className
      )}
      {...props}
    >
      {children}
      <Icon icon="tabler:chevron-right" className="ml-auto h-4 w-4" />
    </MenuPrimitive.SubmenuTrigger>
  )
}
MenubarSubTrigger.displayName = "MenubarSubTrigger"

function MenubarSubContent({
  className,
  align = "start",
  alignOffset = 0,
  side = "right",
  sideOffset = 0,
  ...props
}: WithClassName<MenuPrimitive.Popup.Props> &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          className={cn(contentStyles, className)}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  )
}
MenubarSubContent.displayName = "MenubarSubContent"

function MenubarContent({
  className,
  align = "start",
  alignOffset = -4,
  side,
  sideOffset = 8,
  ...props
}: WithClassName<MenuPrimitive.Popup.Props> &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          className={cn(contentStyles, className)}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  )
}
MenubarContent.displayName = "MenubarContent"

function MenubarItem({
  className,
  inset,
  ...props
}: WithClassName<MenuPrimitive.Item.Props> & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.Item
      className={cn(itemStyles, inset && "pl-8", className)}
      {...props}
    />
  )
}
MenubarItem.displayName = "MenubarItem"

function MenubarCheckboxItem({
  className,
  children,
  checked,
  ...props
}: WithClassName<MenuPrimitive.CheckboxItem.Props>) {
  return (
    <MenuPrimitive.CheckboxItem
      className={cn(itemStyles, "pl-8", className)}
      checked={checked}
      {...props}
    >
      <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
        <MenuPrimitive.CheckboxItemIndicator>
          <Icon icon="tabler:check" className="h-4 w-4 text-primary" />
        </MenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </MenuPrimitive.CheckboxItem>
  )
}
MenubarCheckboxItem.displayName = "MenubarCheckboxItem"

function MenubarRadioItem({
  className,
  children,
  ...props
}: WithClassName<MenuPrimitive.RadioItem.Props>) {
  return (
    <MenuPrimitive.RadioItem
      className={cn(itemStyles, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
        <MenuPrimitive.RadioItemIndicator>
          <span className="h-2 w-2 rounded-full bg-primary" />
        </MenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </MenuPrimitive.RadioItem>
  )
}
MenubarRadioItem.displayName = "MenubarRadioItem"

function MenubarLabel({
  className,
  inset,
  ...props
}: WithClassName<MenuPrimitive.GroupLabel.Props> & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.GroupLabel
      className={cn(
        "px-2 py-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground",
        inset && "pl-8",
        className
      )}
      {...props}
    />
  )
}
MenubarLabel.displayName = "MenubarLabel"

function MenubarSeparator({
  className,
  ...props
}: WithClassName<MenuPrimitive.Separator.Props>) {
  return (
    <MenuPrimitive.Separator
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  )
}
MenubarSeparator.displayName = "MenubarSeparator"

function MenubarShortcut({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      className={cn("ml-auto text-xs tracking-widest text-muted-foreground", className)}
      {...props}
    />
  )
}
MenubarShortcut.displayName = "MenubarShortcut"

export {
  Menubar,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarItem,
  MenubarSeparator,
  MenubarLabel,
  MenubarCheckboxItem,
  MenubarRadioGroup,
  MenubarRadioItem,
  MenubarPortal,
  MenubarSubContent,
  MenubarSubTrigger,
  MenubarGroup,
  MenubarSub,
  MenubarShortcut,
}
